function parseCSV(text,d){const lines=text.trim().split(/\r?\n/).filter(Boolean);if(lines.length<2)return[];const split=line=>{let out=[],cur='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++}else q=!q}else if(c===d&&!q){out.push(cur.trim());cur=''}else cur+=c}out.push(cur.trim());return out};const h=split(lines[0]);return lines.slice(1).map(line=>{const v=split(line);return Object.fromEntries(h.map((x,i)=>[x,v[i]||'']))})}
function parseRows(format,text){if(!text.trim())return[];if(format==='jsonl')return text.trim().split(/\r?\n/).filter(Boolean).map(JSON.parse);return parseCSV(text,format==='tsv'?'\t':',')}
