function bytesToBase64(buffer){const bytes=new Uint8Array(buffer);let binary='';const chunk=32768;for(let i=0;i<bytes.length;i+=chunk)binary+=String.fromCharCode(...bytes.subarray(i,i+chunk));return btoa(binary)}
function metricValue(row,keys){for(const key of keys){const value=row?.[key];if(Number.isFinite(value))return value}return null}
function formatMetric(value){if(!Number.isFinite(value))return '—';const absolute=Math.abs(value);if(absolute&&absolute<.001)return value.toExponential(2);if(absolute>=1000)return value.toLocaleString(undefined,{maximumFractionDigits:1});return value.toLocaleString(undefined,{maximumSignificantDigits:4})}
function words(text){return String(text||'').toLowerCase().match(/[a-z0-9']+/g)||[]}
function rougeL(candidate,reference){const a=words(candidate).slice(0,400),b=words(reference).slice(0,400);if(!a.length||!b.length)return 0;let prev=new Array(b.length+1).fill(0);for(let i=1;i<=a.length;i++){const cur=new Array(b.length+1).fill(0);for(let j=1;j<=b.length;j++)cur[j]=a[i-1]===b[j-1]?prev[j-1]+1:Math.max(prev[j],cur[j-1]);prev=cur}const lcs=prev[b.length];if(!lcs)return 0;const p=lcs/a.length,r=lcs/b.length;return 2*p*r/(p+r)}
function duration(seconds){if(!Number.isFinite(seconds)||seconds<0)return '';const h=Math.floor(seconds/3600),m=Math.round(seconds%3600/60);return h?`${h}h ${m}m`:`${m}m`}
